def show_ports():
    ports = list(list_ports.comports())
    if not ports:
        print("No COM ports found.")
    else:
        print("Available COM ports:")
        for p in ports:
            print(f"  {p.device}: {p.description}")

def main():
    if len(sys.argv) < 2:
        show_ports()
        print("\nUsage: py orgbro_x3_replay.py COM9")
        return 2
    port = sys.argv[1]
    print(f"Opening {port}...")
    # Baud rate is largely ignored by Bluetooth RFCOMM virtual COM ports.
    with serial.Serial(port, 115200, timeout=0.2, write_timeout=5) as ser:
        time.sleep(0.5)
        try:
            ser.reset_input_buffer()
            ser.reset_output_buffer()
        except Exception:
            pass

        # These two short application requests were sent by the Android app before the captured print.
        for cmd in (
            bytes.fromhex("64 11 01 00 00 00 00 00 00"),
            bytes.fromhex("64 12 02 00 00 00 00 00 00"),
        ):
            ser.write(cmd)
            ser.flush()
            time.sleep(0.15)
            reply = ser.read(512)
            if reply:
                print("RX:", reply.hex(" "))

        print(f"Replaying {len(CHUNKS)} captured print chunks...")
        for i, (data, original_delay) in enumerate(CHUNKS, 1):
            # Preserve the app's pacing, but avoid unusually long scheduler gaps.
            if original_delay > 0:
                time.sleep(min(original_delay, 0.20))
            ser.write(data)
            ser.flush()
            print(f"TX {i:02d}/{len(CHUNKS)}: {len(data)} bytes")

        time.sleep(1.0)
        reply = ser.read(4096)
        if reply:
            print("Final RX:", reply.hex(" "))
    print("Done.")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
